import random
import string
from typing import List

# Data type: URL path string
# Goal: produce valid, interesting HTTP request target paths to exercise Crow routing,
# including:
# - root and simple paths
# - nested segments
# - dynamic-looking segments that Crow route builders might use (<int>, <uint>, <double>, <str>, <string>, <path>)
# - numeric segments (signed/unsigned, floating point)
# - percent-encoded characters
# - mixed case, dashes, underscores
# - paths with and without leading slash
# - optional query strings (even though fuzz stubs set req.url only, Router compares strings)
# - prefixes to exercise CORS prefix matching
# Constraints: <= 4096 bytes

SAFE_CHARS = string.ascii_letters + string.digits + "-_"

def _rand_choice(rng: random.Random, seq):
    return seq[rng.randrange(len(seq))]

def _pct_encode(s: str) -> str:
    out = []
    for ch in s:
        o = ord(ch)
        if (
            0x30 <= o <= 0x39 or  # 0-9
            0x41 <= o <= 0x5A or  # A-Z
            0x61 <= o <= 0x7A or  # a-z
            ch in "-._~"
        ):
            out.append(ch)
        else:
            out.append("%{:02X}".format(o))
    return "".join(out)

def _rand_token(rng: random.Random, min_len=1, max_len=10) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(SAFE_CHARS) for _ in range(n))

def _rand_numeric_segment(rng: random.Random) -> str:
    kind = rng.choice(["int", "uint", "float"]) 
    if kind == "int":
        val = rng.randint(-2**31, 2**31 - 1)
        return str(val)
    if kind == "uint":
        # sometimes with explicit plus
        val = rng.randint(0, 2**32 - 1)
        return ("+" if rng.random() < 0.3 else "") + str(val)
    # float
    # cover plain, scientific, leading dot, trailing dot
    base = rng.uniform(-1e6, 1e6)
    choice = rng.randint(0, 3)
    if choice == 0:
        return ("+" if rng.random() < 0.3 else ("-" if rng.random() < 0.3 else "")) + ("{:.6f}".format(base))
    if choice == 1:
        return ("{:.6e}".format(base))
    if choice == 2:
        # leading dot
        frac = rng.randint(0, 999999)
        sign = rng.choice(["", "+", "-"])
        return f"{sign}." + str(frac)
    else:
        # integer with trailing dot
        iv = rng.randint(-10**6, 10**6)
        return f"{iv}."

def _rand_param_placeholder(rng: random.Random) -> str:
    return rng.choice(["<int>", "<uint>", "<double>", "<float>", "<str>", "<string>", "<path>"])

def _rand_segment(rng: random.Random) -> str:
    pick = rng.random()
    if pick < 0.15:
        return _rand_param_placeholder(rng)
    if pick < 0.35:
        return _rand_numeric_segment(rng)
    if pick < 0.55:
        # include percent-encoded specials
        raw = _rand_token(rng, 1, 8)
        # inject a space or slash or unicode to be encoded
        specials = [" ", ":", ";", ",", "|", "[", "]", "{", "}", "#", "?", "=", "+", "\u00E9", "\u2603"]
        raw += _rand_choice(rng, specials)
        raw += _rand_token(rng, 0, 4)
        return _pct_encode(raw)
    if pick < 0.75:
        return _rand_token(rng, 1, 12)
    # mixed tokens with dashes/underscores
    parts = [_rand_token(rng, 1, 5) for _ in range(rng.randint(2, 4))]
    return rng.choice(["-".join(parts), "_".join(parts)])

def _build_path(rng: random.Random) -> str:
    # choose style
    style = rng.randint(0, 8)
    if style == 0:
        return "/"
    if style == 1:
        # no leading slash (to test prefix matching that may or may not expect slash)
        segs = [_rand_segment(rng) for _ in range(rng.randint(1, 4))]
        return "".join([_rand_choice(rng, ["", "/"])]) + "/".join(segs)
    if style == 2:
        # deep path
        segs = [_rand_segment(rng) for _ in range(rng.randint(3, 8))]
        return "/" + "/".join(segs)
    if style == 3:
        # path ending with slash
        segs = [_rand_segment(rng) for _ in range(rng.randint(1, 5))]
        return "/" + "/".join(segs) + "/"
    if style == 4:
        # include a <path> tail
        head = "/" + "/".join(_rand_segment(rng) for _ in range(rng.randint(1, 3)))
        return head + "/<path>"
    if style == 5:
        # numeric heavy
        segs = [_rand_numeric_segment(rng) for _ in range(rng.randint(2, 5))]
        return "/" + "/".join(segs)
    if style == 6:
        # dynamic style like Crow route declarations
        segs: List[str] = []
        for _ in range(rng.randint(2, 5)):
            if rng.random() < 0.6:
                segs.append(_rand_param_placeholder(rng))
            else:
                segs.append(_rand_token(rng, 1, 6))
        return "/" + "/".join(segs)
    if style == 7:
        # percent-encoded heavy
        segs = []
        for _ in range(rng.randint(2, 6)):
            base = _rand_token(rng, 1, 6)
            # insert some spaces or unicode to encode
            insert = _rand_choice(rng, [" ", "#", "?", "+", "\u00E4", "\u20AC"]) + _rand_token(rng, 0, 3)
            segs.append(_pct_encode(base + insert))
        return "/" + "/".join(segs)
    # style 8: CORS-like prefix (short), with possible query
    prefix = "/" + _rand_token(rng, 1, 6)
    tail = "" if rng.random() < 0.5 else "/" + _rand_token(rng, 1, 8)
    path = prefix + tail
    if rng.random() < 0.5:
        # attach simple query to increase variety (Router may ignore, but safe)
        qk = _rand_token(rng, 1, 5)
        qv = _rand_token(rng, 0, 6)
        path += f"?{qk}={_pct_encode(qv)}"
    return path

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Produce a set of candidates and pick one for diversity across seeds
    candidates = []
    count = rng.randint(1, 5)
    for _ in range(count):
        p = _build_path(rng)
        candidates.append(p)
    # Optionally mix in exact prefixes that may be used by the fuzzer (e.g., "/dyn")
    if rng.random() < 0.5:
        candidates.append("/dyn" + ("/" + _rand_token(rng, 1, 6) if rng.random() < 0.7 else ""))
    # Choose one deterministically from rng state
    path = _rand_choice(rng, candidates)
    # Ensure max length
    s = path[:4096]
    return s.encode("utf-8", errors="strict")
